VStack(spacing: theme.spacing.space3) {
    MonarchTabs(
        "Form builder",
        selection: $tab,
        items: [MonarchTabsItem({{tabs.0}}, value: "build"), MonarchTabsItem({{tabs.1}}, value: "preview")]
    )
    if tab == "build" {
        VStack(alignment: .leading, spacing: theme.spacing.space2) {
            MonarchSectionCard({{addField}}) {
                ForEach(groups, id: \.name) { group in
                    VStack(alignment: .leading, spacing: theme.spacing.space1) {
                        Text(group.name)
                            .monarchTextStyle(.caption)
                            .foregroundStyle(theme.colors.textMuted)
                        LazyVGrid(columns: Array(repeating: GridItem(.flexible(), alignment: .leading), count: 3), alignment: .leading) {
                            ForEach(group.types, id: \.0) { type, name in
                                Button {
                                    added += 1
                                    fields.append(MonarchFormFieldDefinition(id: "field\(added)", type: type, label: name))
                                } label: {
                                    Label(name, systemImage: "plus")
                                        .monarchTextStyle(.caption)
                                }
                                .buttonStyle(.plain)
                                .monarchMinimumHitTarget()
                            }
                        }
                    }
                }
            }
            ForEach(fields) { field in
                let isOpen = editing?.id == field.id
                HStack(spacing: theme.spacing.space2) {
                    MonarchDragHandle("Reorder " + field.label, onMove: { move(field, by: $0 == .up ? -1 : 1) })
                        .draggable(field.id)
                    VStack(alignment: .leading, spacing: theme.spacing.space0_5) {
                        Text(field.label)
                            .monarchTextStyle(.label)
                        HStack(spacing: theme.spacing.space1_5) {
                            Text(typeName(field.type))
                                .monarchTextStyle(.caption)
                                .foregroundStyle(theme.colors.textMuted)
                            if field.isRequired { MonarchBadge({{labels.required}}) }
                            if !field.conditions.isEmpty { MonarchBadge({{labels.conditional}}, tone: .info) }
                        }
                    }
                    .frame(maxWidth: .infinity, alignment: .leading)
                    .accessibilityElement(children: .combine)
                    .accessibilityActions {
                        Button("Move up") { move(field, by: -1) }
                        Button("Move down") { move(field, by: 1) }
                    }
                    Button {
                        added += 1
                        var copy = field
                        copy.id = "field\(added)"
                        if let index = fields.firstIndex(of: field) { fields.insert(copy, at: index + 1) }
                    } label: {
                        MonarchIcon(systemName: "doc.on.doc", size: .md).monarchMinimumHitTarget()
                    }
                    .accessibilityLabel("Duplicate \(field.label)")
                    Button {
                        fields.removeAll { $0.id == field.id }
                        if isOpen { editing = nil }
                    } label: {
                        MonarchIcon(systemName: "xmark", size: .md).monarchMinimumHitTarget()
                    }
                    .accessibilityLabel("Remove \(field.label)")
                }
                .buttonStyle(.plain)
                .padding(theme.spacing.space3)
                .background(theme.colors.bgSurface, in: RoundedRectangle(cornerRadius: theme.radius.lg))
                .overlay(
                    RoundedRectangle(cornerRadius: theme.radius.lg).strokeBorder(
                        isOpen ? theme.colors.dangerBorder : theme.colors.borderSubtle,
                        lineWidth: 1
                    )
                )
                .contentShape(Rectangle())
                .onTapGesture { editing = field }
                .dropDestination(for: String.self) { ids, _ in
                    guard let id = ids.first, let from = fields.firstIndex(where: { $0.id == id }),
                        let to = fields.firstIndex(where: { $0.id == field.id })
                    else { return false }
                    fields.move(fromOffsets: IndexSet(integer: from), toOffset: to > from ? to + 1 : to)
                    return true
                }
            }
            if let snapshot = editing, let field = settings(snapshot.id) {
                MonarchSectionCard({{settings.title}}) {
                    MonarchTextField(
                        {{settings.question}},
                        text: field.label,
                        error: field.wrappedValue.label.trimmingCharacters(in: .whitespaces).isEmpty
                            ? "Write the question." : nil,
                        isRequired: true
                    )
                    MonarchTextField(
                        {{settings.help}},
                        text: Binding(
                            get: { field.wrappedValue.description ?? "" },
                            set: { field.wrappedValue.description = $0.isEmpty ? nil : $0 }
                        )
                    )
                    Divider()
                    Text("Show this field when")
                        .monarchTextStyle(.caption)
                        .fontWeight(.semibold)
                    Text("Always shown when there are no conditions. Conditions can use earlier fields only.")
                        .monarchTextStyle(.caption)
                        .foregroundStyle(theme.colors.textMuted)
                    if field.wrappedValue.conditions.isEmpty {
                        Text("No conditions. This applies every time.")
                            .monarchTextStyle(.caption)
                            .foregroundStyle(theme.colors.textMuted)
                    }
                    MonarchButton("Add condition", systemImage: "plus", variant: .secondary, size: .sm) {}
                }
            }
        }
    } else {
        Form {
            ForEach(fields.filter { $0.isVisible(in: answers) }) { field in
                MonarchFieldRenderer(field, value: $answers[field.id])
            }
        }
    }
}

examples.setupTemplate:
@Environment(\.monarchTheme) private var theme
@State private var fields = [
    MonarchFormFieldDefinition(id: {{fields.0.id}}, type: {{fields.0.type|case}}, label: {{fields.0.label}}),
    MonarchFormFieldDefinition(
        id: {{fields.1.id}},
        type: {{fields.1.type|case}},
        label: {{fields.1.label}},
        isRequired: {{fields.1.required}},
        options: [
            MonarchFormFieldOption(value: {{fields.1.options.0.value}}, label: {{fields.1.options.0.label}}),
            MonarchFormFieldOption(value: {{fields.1.options.1.value}}, label: {{fields.1.options.1.label}}),
        ]
    ),
    MonarchFormFieldDefinition(
        id: {{fields.2.id}},
        type: {{fields.2.type|case}},
        label: {{fields.2.label}},
        conditions: [MonarchCondition(id: {{fields.2.condition.id}}, field: {{fields.2.condition.field}}, operator: .equals, value: .text({{fields.2.condition.value}}))]
    ),
    MonarchFormFieldDefinition(id: {{fields.3.id}}, type: {{fields.3.type|case}}, label: {{fields.3.label}}),
]
@State private var tab = "build"
@State private var editing: MonarchFormFieldDefinition? = MonarchFormFieldDefinition(id: {{fields.0.id}}, type: {{fields.0.type|case}}, label: {{fields.0.label}})
@State private var added = 0
@State private var answers: [String: MonarchFormFieldValue] = [:]
private let palette: [(MonarchFormFieldType, String)] = [
    ({{palette.0.type|case}}, {{palette.0.label}}),
    ({{palette.1.type|case}}, {{palette.1.label}}),
    ({{palette.2.type|case}}, {{palette.2.label}}),
    ({{palette.3.type|case}}, {{palette.3.label}}),
]
private var groups: [(name: String, types: [(MonarchFormFieldType, String)])] {
    [
    ("Text", [palette[0], palette[1], (.email, "Email"), (.phone, "Phone"), (.url, "Web address"), (.number, "Number")]),
    ("Other", [(.date, "Date"), (.time, "Time"), (.consent, "Consent"), (.file, "File upload"), palette[3]]),
    ("Choice", [(.select, "Dropdown"), (.multiSelect, "Multiple choice list"), palette[2], (.checkboxes, "Checkboxes"), (.yesNo, "Yes / no"), (.rating, "Rating")]),
]
}

private func typeName(_ type: MonarchFormFieldType) -> String {
    groups.flatMap(\.types).first { $0.0 == type }?.1 ?? type.rawValue
}

private func move(_ field: MonarchFormFieldDefinition, by step: Int) {
    guard let index = fields.firstIndex(of: field), fields.indices.contains(index + step) else { return }
    fields.swapAt(index, index + step)
    AccessibilityNotification.Announcement("\(field.label) moved to position \(index + step + 1) of \(fields.count)").post()
}

private func settings(_ id: String) -> Binding<MonarchFormFieldDefinition>? {
    guard let current = fields.first(where: { $0.id == id }) else { return nil }
    return Binding(
        get: { fields.first { $0.id == id } ?? current },
        set: { edited in
            if let index = fields.firstIndex(where: { $0.id == id }) { fields[index] = edited }
        }
    )
}

